    ('setom', 99, '', 'סְתוֹם פִּיּוֹת מַשְׂטִינֵֽינוּ וּמְקַטְרְגֵֽינוּ.', 'close the mouths of our adversaries and accusers.'),
    ('kaleh_dever', 99, '', 'כַּלֵּה דֶֽבֶר וְחֶֽרֶב וְרָעָב, שְׁבִי וּמַשְׁחִית וְעָוֹן וּשְׁמָד, מִבְּנֵי בְרִיתֶֽךָ.', 'remove pestilence, sword, famine, captivity, destruction, iniquity and persecution from thy people of the covenant.'),
    ('mena', 99, '', 'מְנַע מַגֵּפָה מִנַּחֲלָתֶֽךָ.', 'keep the plague back from thy heritage.'),
    ('selach', 99, '', 'סְלַח וּמְחַל לְכָל עֲוֹנוֹתֵֽינוּ.', 'forgive and pardon all our sins.'),
    ('mecheh', 99, '', 'מְחֵה וְהַעֲבֵר פְּשָׁעֵֽינוּ וְחַטֹּאתֵֽינוּ מִנֶּֽגֶד עֵינֶֽיךָ.', 'blot out and remove our transgressions and sins from thy sight.'),
    ('mechoq', 99, '', 'מְחוֹק בְּרַחֲמֶֽיךָ הָרַבִּים כָּל שִׁטְרֵי חוֹבוֹתֵֽינוּ.', 'cancel in thy abundant mercy all the records of our sins.'),
    ('hachazirenu', 99, '', 'הַחֲזִירֵֽנוּ בִּתְשׁוּבָה שְׁלֵמָה לְפָנֶֽיךָ.', 'bring us back in perfect repentance to thee.'),
    ('shelach', 99, '', 'שְׁלַח רְפוּאָה שְׁלֵמָה לְחוֹלֵי עַמֶּֽךָ.', 'send a perfect healing to the sick among thy people.'),
    ('qera', 99, '', 'קְרַע רֹֽעַ גְּזַר דִּינֵֽנוּ.', 'tear up the evil sentence decreed against us.'),
    ('zokhrenu', 99, '', 'זָכְרֵֽנוּ בְּזִכָּרוֹן טוֹב לְפָנֶֽיךָ.', 'remember us favorably.'),
    ('kotvenu_chayim', 99, 'ten_days', 'כָּתְבֵֽנוּ בְּסֵֽפֶר חַיִּים טוֹבִים.', 'inscribe us in the book of happy life.'),
