    ('kotvenu_parnasah', 99, 'ten_days', 'כָּתְבֵֽנוּ בְּסֵֽפֶר פַּרְנָסָה וְכַלְכָּלָה.', 'inscribe us in the book of maintenance and sustenance.'),
    ('kotvenu_zekhuyot', 99, 'ten_days', 'כָּתְבֵֽנוּ בְּסֵֽפֶר זְכֻיּוֹת.', 'inscribe us in the book of merit.'),
