    ('zokhrenu_chayim', 99, 'fast', 'זָכְרֵֽנוּ לְחַיִּים טוֹבִים.', 'remember us in the book of happy life.'),
    ('zokhrenu_geulah', 99, 'fast', 'זָכְרֵֽנוּ לִגְאֻלָּה וִישׁוּעָה.', 'remember us in the book of redemption and salvation.'),
    ('zokhrenu_parnasah', 99, 'fast', 'זָכְרֵֽנוּ לְפַרְנָסָה וְכַלְכָּלָה.', 'remember us in the book of maintenance and sustenance.'),
    ('zokhrenu_zekhuyot', 99, 'fast', 'זָכְרֵֽנוּ לִזְכֻיּוֹת.', 'remember us in the book of merit.'),
    ('zokhrenu_selichah', 99, 'fast', 'זָכְרֵֽנוּ לִסְלִיחָה וּמְחִילָה.', 'remember us in the book of pardon and forgiveness.'),
    ('hatzmach', 101, '', 'הַצְמַח לָֽנוּ יְשׁוּעָה בְּקָרוֹב.', 'cause our salvation soon to flourish.'),
    ('harem_yisrael', 101, '', 'הָרֵם קֶֽרֶן יִשְׂרָאֵל עַמֶּֽךָ.', 'raise the strength of Israel thy people.'),
    ('harem_meshichekha', 101, '', 'הָרֵם קֶֽרֶן מְשִׁיחֶֽךָ.', 'raise the strength of thy anointed one.'),
    ('male_yadenu', 101, '', 'מַלֵּא יָדֵֽינוּ מִבִּרְכוֹתֶֽיךָ.', 'fill our hands with thy blessings.'),
    ('male_asamenu', 101, '', 'מַלֵּא אֲסָמֵֽינוּ שָׂבָע.', 'fill our storehouses with plenty.'),
    ('shema', 101, '', 'שְׁמַע קוֹלֵֽנוּ, חוּס וְרַחֵם עָלֵֽינוּ.', 'hear our voice, spare us and have mercy on us.'),
    ('qabbel', 101, '', 'קַבֵּל בְּרַחֲמִים וּבְרָצוֹן אֶת תְּפִלָּתֵֽנוּ.', 'receive our prayer with mercy and favor.'),
    ('petach', 101, '', 'פְּתַח שַׁעֲרֵי שָׁמַֽיִם לִתְפִלָּתֵֽנוּ.', 'open the gates of heaven to our prayer.'),
    ('al_teshivenu', 101, '', 'נָא אַל תְּשִׁיבֵֽנוּ רֵיקָם מִלְּפָנֶֽיךָ.', 'dismiss us not empty-handed from thy presence.'),
    ('zekhor', 101, '', 'זְכוֹר כִּי עָפָר אֲנָֽחְנוּ.', 'remember that we are but dust.'),
    ('tehe', 101, '', 'תְּהֵא הַשָּׁעָה הַזֹּאת שְׁעַת רַחֲמִים וְעֵת רָצוֹן מִלְּפָנֶֽיךָ.', 'may this hour be an hour of mercy and a time of grace with thee.'),
    ('chamol', 101, '', 'חֲמוֹל עָלֵֽינוּ וְעַל עוֹלָלֵֽינוּ וְטַפֵּֽנוּ.', 'have compassion on us, on our children and our infants.'),
    ('aseh_harugim', 101, '', 'עֲשֵׂה לְמַֽעַן הֲרוּגִים עַל שֵׁם קָדְשֶֽׁךָ.', 'act for the sake of those who were slain for thy holy name.'),
    ('aseh_tevuchim', 101, '', 'עֲשֵׂה לְמַֽעַן טְבוּחִים עַל יִחוּדֶֽךָ.', 'act for the sake of those who were slaughtered for proclaiming thy Oneness.'),
    ('aseh_baei', 101, '', 'עֲשֵׂה לְמַֽעַן בָּאֵי בָאֵשׁ וּבַמַּֽיִם עַל קִדּוּשׁ שְׁמֶֽךָ.', 'act for the sake of those who went through fire and water for the sanctification of thy name.'),
    ('neqom', 101, '', 'נְקוֹם נִקְמַת דַּם עֲבָדֶֽיךָ הַשָּׁפוּךְ.', 'avenge the spilt blood of thy servants.'),
    ('aseh_lemaanekha', 101, '', 'עֲשֵׂה לְמַעַנְךָ אִם לֹא לְמַעֲנֵֽנוּ.', 'do it for thy sake, if not for ours.'),
    ('aseh_vehoshienu', 101, '', 'עֲשֵׂה לְמַעַנְךָ וְהוֹשִׁיעֵֽנוּ.', 'do it for thy sake and save us.'),
    ('aseh_rachamekha', 101, '', 'עֲשֵׂה לְמַֽעַן רַחֲמֶֽיךָ הָרַבִּים.', 'do it for the sake of thy abundant mercy.'),
    ('aseh_shimkha', 101, '', 'עֲשֵׂה לְמַֽעַן שִׁמְךָ הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא שֶׁנִּקְרָא עָלֵֽינוּ.', 'do it for the sake of thy great, mighty and revered name by which we are called.'),
    ('chonenu', 101, '', 'חָנֵּֽנוּ וַעֲנֵֽנוּ, כִּי אֵין בָּֽנוּ מַעֲשִׂים; עֲשֵׂה עִמָּֽנוּ צְדָקָה וָחֶֽסֶד וְהוֹשִׁיעֵֽנוּ.', 'be gracious to us and answer us, though we have no merits; deal charitably and kindly with us and save us.'),
